SELECT CASE WHEN duration_sec >= 488 THEN 'high' WHEN duration_sec >= 106 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, ROUND((100 * SUM(CASE WHEN page = '/product' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_product FROM web_events WHERE page IN ('/cart', '/home') GROUP BY 1 HAVING COUNT(CASE WHEN page = '/checkout' THEN 1 END) > 5;
